#ifndef ASM101SA_READLISTING_H
#define ASM101SA_READLISTING_H

#include "common.h"

/*
 * One control section's memory image.  A byte is either a value 0-255 or
 * "nothing was said about this address", which the Python spells as None and
 * which the comparison depends on -- the listing prints a statement with
 * neither location nor object code in places where the location counter still
 * advances, and those addresses cannot contradict the assembler.
 */
typedef struct
{
  char *name;
  int16_t *memory; /* -1 where the listing says nothing */
  size_t len;
  size_t cap;
} ListSect;

typedef struct
{
  ListSect *sects;
  size_t n;
  size_t cap;
} Listing;

/* Returns NULL where the Python returns None. */
Listing *readListing (const char *filename);
ListSect *listing_find (Listing *l, const char *name);

#endif /* ASM101SA_READLISTING_H */
